def is_palindrome_number(n):
    s = str(n)
    return s == s[::-1]

def power(base, exp):
    if exp == 0:
        return 1
    half = power(base, exp // 2)
    result = half * half
    if exp % 2 == 1:
        result *= base
    return result

def is_anagram_v1(a, b):
    return set(a) == set(b)

def is_anagram_v2(a, b):
    return sorted(a) == sorted(b)
